1	/**
2	 * Batch notifications for AI schedule publish.
3	 *
4	 * When a sandbox draft is published, this module consolidates per-event
5	 * notifications into a single SMS + email per recipient instead of
6	 * flooding users with one message per event.
7	 */
8	
9	import { db } from '@/lib/db';
10	import { sendEventConfirmationEmails } from '@/lib/email-events';
11	import { sendGuardedSms } from '@/lib/guarded-sms';
12	import * as schema from '@/lib/schema';
13	import { normalizePhoneToE164 } from '@/lib/sms';
14	import {
15	  buildEventEmailContext,
16	  getEventEmailSettings,
17	} from '@/server/utils/event-email-context';
18	import { and, eq, inArray } from 'drizzle-orm';
19	
20	// ─── Types ────────────────────────────────────────────────────────────────
21	
22	interface PublishedEvent {
23	  id: string;
24	  title: string;
25	  startAt: Date;
26	  endAt?: Date | null;
27	  studentId?: string | null;
28	  instructorId?: string | null;
29	  aircraftId?: string | null;
30	  type?: string | null;
31	  notes?: string | null;
32	  [key: string]: unknown;
33	}
34	
35	interface RecipientInfo {
36	  id: string;
37	  name: string | null;
38	  phone: string | null;
39	}
40	
41	// ─── Helpers ──────────────────────────────────────────────────────────────
42	
43	function formatEventLine(
44	  event: PublishedEvent,
45	  timezone: string,
46	  extra?: string,
47	): string {
48	  const start = event.startAt;
49	  const dateStr = start.toLocaleDateString('en-US', {
50	    weekday: 'short',
51	    month: 'short',
52	    day: 'numeric',
53	    timeZone: timezone,
54	  });
55	  const timeStr = start.toLocaleTimeString('en-US', {
56	    hour: 'numeric',
57	    minute: '2-digit',
58	    hour12: true,
59	    timeZone: timezone,
60	  });
61	  const title = event.title || 'Scheduled Event';
62	  return extra
63	    ? `${dateStr} ${timeStr} - ${title} ${extra}`
64	    : `${dateStr} ${timeStr} - ${title}`;
65	}
66	
67	async function hasSmsConsent(
68	  flightSchoolId: string,
69	  phone: string,
70	): Promise<boolean> {
71	  const normalized = normalizePhoneToE164(phone);
72	  if (!normalized) return false;
73	  const [row] = await db
74	    .select({
75	      consented: schema.smsConsent.consented,
76	      optedOut: schema.smsConsent.optedOut,
77	    })
78	    .from(schema.smsConsent)
79	    .where(
80	      and(
81	        eq(schema.smsConsent.flightSchoolId, flightSchoolId),
82	        eq(schema.smsConsent.phone, normalized),
83	      ),
84	    )
85	    .limit(1);
86	  if (!row) return false;
87	  return row.consented && !row.optedOut;
88	}
89	
90	// ─── Batch SMS ────────────────────────────────────────────────────────────
91	
92	/**
93	 * Send ONE consolidated SMS per student and ONE per instructor,
94	 * listing all their newly published events.
95	 */
96	export async function sendBatchScheduleSms(
97	  events: PublishedEvent[],
98	  flightSchoolId: string,
99	  locationId: string,
100	): Promise<void> {
101	  if (events.length === 0) return;
102	
103	  try {
104	    // Get location timezone
105	    const [locRow] = await db
106	      .select({ timezone: schema.locations.timezone })
107	      .from(schema.locations)
108	      .where(eq(schema.locations.id, locationId))
109	      .limit(1);
110	    const timezone = locRow?.timezone ?? 'America/Phoenix';
111	
112	    // Group events by studentId and instructorId
113	    const studentEvents = new Map<string, PublishedEvent[]>();
114	    const instructorEvents = new Map<string, PublishedEvent[]>();
115	
116	    for (const evt of events) {
117	      if (evt.studentId) {
118	        if (!studentEvents.has(evt.studentId))
119	          studentEvents.set(evt.studentId, []);
120	        studentEvents.get(evt.studentId)?.push(evt);
121	      }
122	      if (evt.instructorId) {
123	        const rawId = (evt.instructorId as string).startsWith('instructor-')
124	          ? (evt.instructorId as string).slice('instructor-'.length)
125	          : (evt.instructorId as string);
126	        if (!instructorEvents.has(rawId)) instructorEvents.set(rawId, []);
127	        instructorEvents.get(rawId)?.push(evt);
128	      }
129	    }
130	
131	    // Batch-fetch all recipient info (avoid N+1 queries)
132	    const allUserIds = [
133	      ...new Set([...studentEvents.keys(), ...instructorEvents.keys()]),
134	    ];
135	    const recipientMap = new Map<string, RecipientInfo>();
136	
137	    if (allUserIds.length > 0) {
138	      const users = await db
139	        .select({
140	          id: schema.users.id,
141	          name: schema.users.name,
142	          phone: schema.users.phone,
143	        })
144	        .from(schema.users)
145	        .where(inArray(schema.users.id, allUserIds));
146	      for (const u of users) {
147	        recipientMap.set(u.id, u);
148	      }
149	    }
150	
151	    // Batch-fetch aircraft tail numbers
152	    const aircraftIds = [
153	      ...new Set(
154	        events
155	          .map((e) => e.aircraftId as string)
156	          .filter((id) => id && id.length > 0),
157	      ),
158	    ];
159	    const aircraftMap = new Map<string, string>();
160	    if (aircraftIds.length > 0) {
161	      const aircraft = await db
162	        .select({
163	          id: schema.equipment.id,
164	          tailNumber: schema.equipment.tailNumber,
165	        })
166	        .from(schema.equipment)
167	        .where(inArray(schema.equipment.id, aircraftIds));
168	      for (const a of aircraft) {
169	        aircraftMap.set(a.id, a.tailNumber ?? '');
170	      }
171	    }
172	
173	    // Send consolidated SMS to each student
174	    for (const [studentId, studentEvts] of studentEvents) {
175	      const recipient = recipientMap.get(studentId);
176	      if (!recipient?.phone) continue;
177	
178	      const normalized = normalizePhoneToE164(recipient.phone);
179	      if (!normalized) continue;
180	
181	      const consented = await hasSmsConsent(flightSchoolId, normalized);
182	      if (!consented) continue;
183	
184	      // Sort events by date/time
185	      const sorted = studentEvts.sort(
186	        (a, b) => a.startAt.getTime() - b.startAt.getTime(),
187	      );
188	
189	      // Build consolidated message
190	      const lines = sorted.map((evt) => {
191	        const instrInfo = evt.instructorId
192	          ? recipientMap.get(
193	              (evt.instructorId as string).startsWith('instructor-')
194	                ? (evt.instructorId as string).slice('instructor-'.length)
195	                : (evt.instructorId as string),
196	            )
197	          : null;
198	        const instrName = instrInfo?.name || '';
199	        const acTail = evt.aircraftId
200	          ? aircraftMap.get(evt.aircraftId as string) || ''
201	          : '';
202	        const extra = [
203	          instrName ? `with ${instrName}` : '',
204	          acTail ? `on ${acTail}` : '',
205	        ]
206	          .filter(Boolean)
207	          .join(' ');
208	        return formatEventLine(evt, timezone, extra);
209	      });
210	
211	      const message = `Hi ${recipient.name || 'there'}, your schedule has been updated with ${sorted.length} new session${sorted.length !== 1 ? 's' : ''}:\n\n${lines.join('\n')}`;
212	
213	      await sendGuardedSms({
214	        to: normalized,
215	        body: message,
216	        flightSchoolId,
217	        recipientUserId: studentId,
218	        payloadSummary: { source: 'schedule_batch_student' },
219	      });
220	
221	      // Audit log
222	      await db
223	        .insert(schema.smsLogs)
224	        .values({
225	          flightSchoolId,
226	          toPhone: normalized,
227	          recipientUserId: studentId,
228	          body: message,
229	          status: 'sent',
230	        })
231	        .catch(() => {});
232	    }
233	
234	    // Send consolidated SMS to each instructor
235	    for (const [instructorId, instrEvts] of instructorEvents) {
236	      const recipient = recipientMap.get(instructorId);
237	      if (!recipient?.phone) continue;
238	
239	      const normalized = normalizePhoneToE164(recipient.phone);
240	      if (!normalized) continue;
241	
242	      const consented = await hasSmsConsent(flightSchoolId, normalized);
243	      if (!consented) continue;
244	
245	      const sorted = instrEvts.sort(
246	        (a, b) => a.startAt.getTime() - b.startAt.getTime(),
247	      );
248	
249	      const lines = sorted.map((evt) => {
250	        const studentInfo = evt.studentId
251	          ? recipientMap.get(evt.studentId as string)
252	          : null;
253	        const studentName = studentInfo?.name || '';
254	        const acTail = evt.aircraftId
255	          ? aircraftMap.get(evt.aircraftId as string) || ''
256	          : '';
257	        const extra = [
258	          studentName ? `with ${studentName}` : '',
259	          acTail ? `on ${acTail}` : '',
260	        ]
261	          .filter(Boolean)
262	          .join(' ');
263	        return formatEventLine(evt, timezone, extra);
264	      });
265	
266	      const message = `Hi ${recipient.name || 'there'}, ${sorted.length} new session${sorted.length !== 1 ? 's have' : ' has'} been added to your schedule:\n\n${lines.join('\n')}`;
267	
268	      await sendGuardedSms({
269	        to: normalized,
270	        body: message,
271	        flightSchoolId,
272	        recipientUserId: instructorId,
273	        payloadSummary: { source: 'schedule_batch_instructor' },
274	      });
275	
276	      await db
277	        .insert(schema.smsLogs)
278	        .values({
279	          flightSchoolId,
280	          toPhone: normalized,
281	          recipientUserId: instructorId,
282	          body: message,
283	          status: 'sent',
284	        })
285	        .catch(() => {});
286	    }
287	  } catch (err) {
288	    console.error(
289	      '[batch-notifications] Error sending batch SMS:',
290	      err instanceof Error ? err.message : String(err),
291	    );
292	  }
293	}
294	
295	// ─── Batch Email ──────────────────────────────────────────────────────────
296	
297	/**
298	 * Send ONE consolidated confirmation email per student and ONE per instructor,
299	 * covering all their newly published events.
300	 */
301	export async function sendBatchScheduleConfirmationEmails(
302	  events: PublishedEvent[],
303	  flightSchoolId: string,
304	  locationId: string,
305	): Promise<void> {
306	  if (events.length === 0) return;
307	
308	  try {
309	    const emailSettings = await getEventEmailSettings(locationId);
310	
311	    // For email, we still use the existing per-event email infrastructure
312	    // but group events and send one email per unique student/instructor.
313	    // The first event in each group provides the email context; additional
314	    // events are listed in the email body via the notes field.
315	
316	    // Group by studentId
317	    const studentEvents = new Map<string, PublishedEvent[]>();
318	    for (const evt of events) {
319	      if (evt.studentId) {
320	        if (!studentEvents.has(evt.studentId as string))
321	          studentEvents.set(evt.studentId as string, []);
322	        studentEvents.get(evt.studentId as string)?.push(evt);
323	      }
324	    }
325	
326	    // Group by instructorId
327	    const instructorEvents = new Map<string, PublishedEvent[]>();
328	    for (const evt of events) {
329	      if (evt.instructorId) {
330	        const rawId = (evt.instructorId as string).startsWith('instructor-')
331	          ? (evt.instructorId as string).slice('instructor-'.length)
332	          : (evt.instructorId as string);
333	        if (!instructorEvents.has(rawId)) instructorEvents.set(rawId, []);
334	        instructorEvents.get(rawId)?.push(evt);
335	      }
336	    }
337	
338	    // Send one email per student using the first event as context
339	    // with a note listing all other events
340	    for (const [, studentEvts] of studentEvents) {
341	      if (studentEvts.length === 0) continue;
342	      const primaryEvent = studentEvts[0];
343	
344	      // Build context from first event — email template renders the primary
345	      // event details. For multi-event batches, append a summary to notes.
346	      const ctx = await buildEventEmailContext(
347	        flightSchoolId,
348	        locationId,
349	        primaryEvent as unknown as Parameters<typeof buildEventEmailContext>[2],
350	      );
351	
352	      if (studentEvts.length > 1) {
353	        // Append additional events info to the context notes
354	        const additional = studentEvts
355	          .slice(1)
356	          .map((evt) => {
357	            const start = evt.startAt;
358	            return `${start.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })} at ${start.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true })} — ${evt.title || 'Event'}`;
359	          })
360	          .join('\n');
361	        ctx.event.notes =
362	          `${ctx.event.notes || ''}\n\nAdditional sessions scheduled:\n${additional}`.trim();
363	      }
364	
365	      await sendEventConfirmationEmails(ctx, emailSettings, flightSchoolId);
366	    }
367	
368	    // Send one email per instructor
369	    for (const [, instrEvts] of instructorEvents) {
370	      if (instrEvts.length === 0) continue;
371	      const primaryEvent = instrEvts[0];
372	
373	      const ctx = await buildEventEmailContext(
374	        flightSchoolId,
375	        locationId,
376	        primaryEvent as unknown as Parameters<typeof buildEventEmailContext>[2],
377	      );
378	
379	      if (instrEvts.length > 1) {
380	        const additional = instrEvts
381	          .slice(1)
382	          .map((evt) => {
383	            const start = evt.startAt;
384	            return `${start.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })} at ${start.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true })} — ${evt.title || 'Event'}`;
385	          })
386	          .join('\n');
387	        ctx.event.notes =
388	          `${ctx.event.notes || ''}\n\nAdditional sessions scheduled:\n${additional}`.trim();
389	      }
390	
391	      await sendEventConfirmationEmails(ctx, emailSettings, flightSchoolId);
392	    }
393	  } catch (err) {
394	    console.error(
395	      '[batch-notifications] Error sending batch emails:',
396	      err instanceof Error ? err.message : String(err),
397	    );
398	  }
399	}
