2189	export function findScheduleMoveConflictForTargets(
2190	  targets: ScheduleMoveTarget[],
2191	  events: ScheduleEvent[],
2192	  resources: Resource[],
2193	) {
2194	  if (targets.length === 0) return null;
2195	  const targetResource = resources.find(
2196	    (resource) => resource.id === targets[0].resourceId,
2197	  );
2198	  if (!targetResource) return null;
2199	  const isExclusiveResource =
2200	    targetResource.type === 'aircraft' ||
2201	    targetResource.type === 'simulator' ||
2202	    targetResource.type === 'instructor' ||
2203	    targetResource.type === 'meeting_room';
2204	  if (!isExclusiveResource) return null;
2205	
2206	  const selectedIds = new Set(targets.map((target) => target.event.id));
2207	  for (let i = 0; i < targets.length; i += 1) {
2208	    for (let j = i + 1; j < targets.length; j += 1) {
2209	      if (
2210	        doScheduleRangesOverlap(
2211	          {
2212	            date: targets[i].event.date,
2213	            startHour: targets[i].startHour,
2214	            endHour: targets[i].endHour,
2215	          },
2216	          {
2217	            date: targets[j].event.date,
2218	            startHour: targets[j].startHour,
2219	            endHour: targets[j].endHour,
2220	          },
2221	        )
2222	      ) {
2223	        return {
2224	          targetResource,
2225	          movingEvent: targets[i].event,
2226	          conflictEvent: targets[j].event,
2227	        };
2228	      }
2229	    }
2230	  }
2231	
2232	  const eventUsesTargetResource = (event: ScheduleEvent) => {
2233	    if (
2234	      targetResource.type === 'aircraft' ||
2235	      targetResource.type === 'simulator'
2236	    ) {
2237	      return (
2238	        event.aircraftId === targetResource.id ||
2239	        event.resourceId === targetResource.id
2240	      );
2241	    }
2242	    if (targetResource.type === 'meeting_room') {
2243	      return (
2244	        event.meetingRoomId === targetResource.id ||
2245	        event.resourceId === targetResource.id
2246	      );
2247	    }
2248	    const instructorIds = event.instructorIds?.length
2249	      ? event.instructorIds
2250	      : event.instructorId
2251	        ? [event.instructorId]
2252	        : [];
2253	    return (
2254	      instructorIds.includes(targetResource.id) ||
2255	      event.resourceId === targetResource.id
2256	    );
2257	  };
2258	
2259	  for (const target of targets) {
2260	    const conflictEvent = events.find((event) => {
2261	      if (selectedIds.has(event.id)) return false;
2262	      if (CONFLICT_IGNORED_STATUSES.has(event.status ?? '')) return false;
2263	      if (!eventUsesTargetResource(event)) return false;
2264	      return doScheduleRangesOverlap(
2265	        {
2266	          date: target.event.date,
2267	          startHour: target.startHour,
2268	          endHour: target.endHour,
2269	        },
2270	        event,
2271	      );
2272	    });
2273	    if (conflictEvent) {
2274	      return {
2275	        targetResource,
2276	        movingEvent: target.event,
2277	        conflictEvent,
2278	      };
2279	    }
2280	  }
2281	
2282	  return null;
2283	}
