2338	export function groupScheduleEventTypesByCategory<
2339	  T extends SearchableEventType,
2340	>(eventTypes: readonly T[]): ScheduleEventTypeCategoryGroup<T>[] {
2341	  const configuredCategoryOrder = new Map<string, number>(
2342	    EVENT_CATEGORIES.map((category, index) => [category, index]),
2343	  );
2344	  const groups = new Map<string, T[]>();
2345	
2346	  [...eventTypes]
2347	    .sort((a, b) => a.sortOrder - b.sortOrder)
2348	    .forEach((eventType) => {
2349	      const category = getScheduleEventTypeCategory(eventType);
