2351	      categoryEventTypes.push(eventType);
2352	      groups.set(category, categoryEventTypes);
2353	    });
2354	
2355	  return [...groups.entries()]
2356	    .sort(([categoryA], [categoryB]) => {
2357	      const orderA =
2358	        configuredCategoryOrder.get(categoryA) ?? Number.MAX_SAFE_INTEGER;
2359	      const orderB =
2360	        configuredCategoryOrder.get(categoryB) ?? Number.MAX_SAFE_INTEGER;
2361	
2362	      return orderA - orderB || categoryA.localeCompare(categoryB);
2363	    })
2364	    .map(([category, categoryEventTypes]) => ({
2365	      category,
2366	      eventTypes: categoryEventTypes,
2367	    }));
