420	export function sortAircraftByMaintenanceDue(
421	  aircraft: Resource[],
422	  indicators: Map<string, AircraftMaintenanceIndicator>,
423	): Resource[] {
424	  return aircraft
425	    .map((resource, index) => ({
426	      resource,
427	      index,
428	      indicator: indicators.get(resource.id),
429	    }))
430	    .sort((a, b) => {
431	      const aGrounded = a.resource.status === 'grounded';
432	      const bGrounded = b.resource.status === 'grounded';
433	      if (aGrounded !== bGrounded) return aGrounded ? 1 : -1;
434	
435	      const aScore = normalizedMaintenanceDueScore(a.indicator);
436	      const bScore = normalizedMaintenanceDueScore(b.indicator);
437	      const aHasDueScore = aScore !== null;
438	      const bHasDueScore = bScore !== null;
439	      if (aHasDueScore !== bHasDueScore) return aHasDueScore ? 1 : -1;
440	      if (aScore !== null && bScore !== null && aScore !== bScore) {
441	        return bScore - aScore;
442	      }
443	
444	      const aSquawks = a.indicator?.openSquawksCount ?? 0;
445	      const bSquawks = b.indicator?.openSquawksCount ?? 0;
446	      if (aSquawks !== bSquawks) return aSquawks - bSquawks;
447	
448	      return a.index - b.index;
449	    })
450	    .map(({ resource }) => resource);
451	}
