1705	        ? `ends ${rule.endDate}`
1706	        : 'no end date';
1707	
1708	  if (rule.frequency === 'daily') {
1709	    return `Every day — ${endStr}`;
1710	  }
1711	  if (rule.frequency === 'weekdays') {
1712	    return `Every weekday (Mon–Fri) — ${endStr}`;
1713	  }
1714	  if (rule.frequency === 'weekly') {
1715	    const days =
1716	      rule.days && rule.days.length > 0
1717	        ? rule.days.map((d) => dayAbbr[d]).join(', ')
1718	        : 'same day';
1719	    return `Every week on ${days} — ${endStr}`;
1720	  }
1721	  if (rule.frequency === 'biweekly') {
1722	    const days =
1723	      rule.days && rule.days.length > 0
1724	        ? rule.days.map((d) => dayAbbr[d]).join(', ')
1725	        : 'same day';
1726	    return `Every 2 weeks on ${days} — ${endStr}`;
1727	  }
1728	  if (rule.frequency === 'monthly') {
1729	    if (rule.monthlyType === 'weekday_of_month' && rule.monthlyWeekday) {
1730	      const ord =
1731	        ordinalLabel[rule.monthlyWeekday.ordinal] ??
1732	        rule.monthlyWeekday.ordinal;
1733	      const wd = dayAbbr[rule.monthlyWeekday.day];
1734	      return `Monthly on the ${ord} ${wd} — ${endStr}`;
1735	    }
1736	    const day = rule.monthlyDay ?? 1;
1737	    return `Monthly on day ${day} — ${endStr}`;
1738	  }
1739	  if (rule.frequency === 'custom') {
1740	    const n = rule.interval ?? 1;
1741	    const unit = rule.unit ?? 'weeks';
1742	    if (unit === 'days') {
1743	      return `Every ${n} day${n !== 1 ? 's' : ''} — ${endStr}`;
1744	    }
1745	    if (unit === 'weeks') {
