1748	          ? rule.days.map((d) => dayAbbr[d]).join(', ')
1749	          : 'same day';
1750	      return `Every ${n} week${n !== 1 ? 's' : ''} on ${days} — ${endStr}`;
1751	    }
1752	    if (unit === 'months') {
1753	      return `Every ${n} month${n !== 1 ? 's' : ''} — ${endStr}`;
1754	    }
1755	  }
1756	  return 'Recurring event';
1757	}
